insert into public.kpi_targets(id,activity_id,product_id,target_value,effective_from,changed_by) values('10000000-0000-4000-8000-000000000060','10000000-0000-4000-8000-000000000020',null,18,now()-interval '1 day','10000000-0000-4000-8000-000000000001'),('10000000-0000-4000-8000-000000000061','10000000-0000-4000-8000-000000000020','10000000-0000-4000-8000-000000000030',22,now()-interval '1 day','10000000-0000-4000-8000-000000000001');
set local role anon;
do $$ begin begin perform public.app_context();raise exception 'FAIL anonymous RPC allowed';exception when insufficient_privilege then null;end;begin perform * from public.profiles;raise exception 'FAIL anonymous read allowed';exception when insufficient_privilege then null;end;end $$;
reset role;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
do $$ declare c jsonb; req jsonb; s jsonb; base timestamptz=now()-interval '240 seconds'; sid uuid='10000000-0000-4000-8000-000000000070';m record;begin
 c=public.app_context();assert c->'profile'->>'name'='QA Worker','auth profile';assert c->'permissions'='["my_work.access"]'::jsonb,'employee has no management permissions';
 assert (select count(*) from public.profiles)=1,'RLS employee isolation';assert (select count(*) from public.activities)=1,'activity filtering';assert (select count(*) from public.kpi_targets)=0,'KPI targets hidden OFF';assert (select count(*) from public.assignments)=1,'own assignments';
 begin perform public.manage('positions','{"name":"Unauthorized"}');raise exception 'FAIL admin RPC allowed';exception when insufficient_privilege then null;end;
 begin insert into public.positions(name) values('Unauthorized direct');raise exception 'FAIL direct write allowed';exception when insufficient_privilege then null;end;
 begin update public.profiles set active=false;raise exception 'FAIL direct update allowed';exception when insufficient_privilege then null;end;
 begin delete from public.profiles;raise exception 'FAIL direct delete allowed';exception when insufficient_privilege then null;end;
 req=jsonb_build_object('request_id','10000000-0000-4000-8000-000000000080','session_id',sid,'action','start','at',base,'expected_revision',0,'activity_id','10000000-0000-4000-8000-000000000020','product_id','10000000-0000-4000-8000-000000000030','assignment_id','10000000-0000-4000-8000-000000000040');
 s=public.session_command(req);assert s->>'status'='running','starts session';assert public.session_command(req)=s,'idempotent start';assert (select count(*) from public.sessions)=1,'no duplicate session';
 begin perform public.session_command(req||'{"request_id":"10000000-0000-4000-8000-000000000081","session_id":"10000000-0000-4000-8000-000000000071"}'::jsonb);raise exception 'FAIL second active session allowed';exception when serialization_failure then null;end;
 begin perform public.session_command(req||'{"product_id":"10000000-0000-4000-8000-000000000031"}'::jsonb);raise exception 'FAIL reused key allowed';exception when invalid_parameter_value then null;end;
 s=public.session_command(jsonb_build_object('request_id','10000000-0000-4000-8000-000000000082','session_id',sid,'action','transition','at',base+interval '60 seconds','expected_revision',1,'kind','WALKING'));
 s=public.session_command(jsonb_build_object('request_id','10000000-0000-4000-8000-000000000083','session_id',sid,'action','transition','at',base+interval '90 seconds','expected_revision',2,'kind','WORK'));
 s=public.session_command(jsonb_build_object('request_id','10000000-0000-4000-8000-000000000084','session_id',sid,'action','transition','at',base+interval '150 seconds','expected_revision',3,'kind','INTERRUPTION'));
 s=public.session_command(jsonb_build_object('request_id','10000000-0000-4000-8000-000000000085','session_id',sid,'action','transition','at',base+interval '180 seconds','expected_revision',4,'kind','WORK'));
 assert jsonb_array_length(s->'segments')=5,'individual segment audit trail';
 begin perform public.session_command(jsonb_build_object('request_id',gen_random_uuid(),'session_id',sid,'action','finish','at',base+interval '200 seconds','expected_revision',1));raise exception 'FAIL stale revision allowed';exception when serialization_failure then null;end;
 s=public.session_command(jsonb_build_object('request_id','10000000-0000-4000-8000-000000000086','session_id',sid,'action','finish','at',base+interval '240 seconds','expected_revision',5));
 assert s->>'status'='awaiting_quantity','Finish stops timer before quantity';assert (select count(*) from public.segments where ended_at is null)=0,'no open segment after finish';assert public.active_session()->>'id'=sid::text,'pending quantity restored';
 begin perform public.session_command(jsonb_build_object('request_id',gen_random_uuid(),'session_id',sid,'action','complete','at',now(),'expected_revision',6,'quantity',-1));raise exception 'FAIL negative quantity allowed';exception when raise_exception then if SQLERRM='FAIL negative quantity allowed' then raise;end if;end;
 req=jsonb_build_object('request_id','10000000-0000-4000-8000-000000000087','session_id',sid,'action','complete','at',now(),'expected_revision',6,'quantity',12);s=public.session_command(req);assert public.session_command(req)=s,'completion idempotency';
 select * into m from public.session_metrics where id=sid;assert m.work_seconds=180,'productive seconds';assert m.walking_seconds=30,'walking seconds';assert m.interruption_seconds=30,'interruption seconds';assert m.total_seconds=240,'total seconds';assert m.walking_events=1,'walking count';assert m.quantity*3600.0/m.work_seconds=240,'productive rate';assert m.quantity*3600.0/m.total_seconds=180,'elapsed rate';assert public.active_session() is null,'finished session cleared';
 assert public.employee_kpi(sid)='{"visibility":"OFF"}'::jsonb,'OFF response hides target';
end $$;
reset role;
-- Labels survive source edits; completed target version is retained.
