set local role authenticated;
do $$ declare p jsonb;a jsonb;r jsonb;begin
 assert private.can('analytics.view'),'admin permissions';assert (select count(*) from public.sessions)=1,'management reads all sessions';
 p=public.manage('positions','{"name":"QA new position","active":true}');
 a=public.manage('activities',jsonb_build_object('name','QA new activity','active',true,'position_ids',jsonb_build_array(p->>'id')));
 assert exists(select 1 from public.activities where id=(a->>'id')::uuid),'configurable activity';
