 perform public.manage('profile_roles',jsonb_build_object('id','10000000-0000-4000-8000-000000000003','role_ids',jsonb_build_array(r->>'id')));
 begin perform public.manage('profile_roles','{"id":"10000000-0000-4000-8000-000000000001","role_ids":[]}');raise exception 'FAIL last admin removed';exception when raise_exception then if SQLERRM='FAIL last admin removed' then raise;end if;end;
end $$;
