 perform public.manage('kpi_targets',jsonb_build_object('id','10000000-0000-4000-8000-000000000060','activity_id','10000000-0000-4000-8000-000000000020','target_value',27,'active',true,'effective_from',now()+interval '1 day'));
end $$;
reset role;
