set local role authenticated;
do $$ declare req jsonb; sid uuid='10000000-0000-4000-8000-000000000072';begin
 req=jsonb_build_object('request_id',gen_random_uuid(),'session_id',sid,'action','start','at',now(),'expected_revision',0,'activity_id','10000000-0000-4000-8000-000000000021','product_id','10000000-0000-4000-8000-000000000031');
 begin perform public.session_command(req);raise exception 'FAIL wrong-position activity allowed';exception when insufficient_privilege then null;end;
 perform public.session_command(req||'{"activity_id":"10000000-0000-4000-8000-000000000020"}'::jsonb);
 assert public.employee_kpi(sid)->>'target'='18','activity fallback preserved before scheduled revision';
 assert public.employee_kpi('10000000-0000-4000-8000-000000000070')->>'target'='22','historical target remains immutable';
